import { describe, it, expect } from 'vitest';
import {
  buildMatchCandidates,
  isCategoryConsistent,
  bestCatalogMatch,
  shouldAutoLock,
  DEFAULT_MATCH_THRESHOLD,
} from '@/shared/lib/productMatch';

// Catálogo realista da Momma (subset), incluindo o produto que causava o
// match errado da regressão ("Mini de Chocolate") e os produtos canônicos
// usados no caso real de "milho" sob "Caseirinhos".
const CATALOG = [
  { id: 1, nome: 'Bolo no Pote Chocolate' },
  { id: 2, nome: 'Bolo no Pote Banoffee' },
  { id: 3, nome: 'Bolo no Pote Ninho' },
  { id: 4, nome: 'Mini de Chocolate' },
  { id: 5, nome: 'Mini Ferrero Rocher' },
  { id: 6, nome: 'Gelato Chocolate' },
  { id: 7, nome: 'Tartelete Chocomelo' },
  { id: 8, nome: 'Bombom Morango' },
  // Produtos do caso real (A4): insumo homônimo e canônico correto
  { id: 9, nome: 'Milho' },
  { id: 10, nome: 'Mini Caseirinho Milho' },
  { id: 11, nome: 'Mini Brigadeiro' },
];

describe('buildMatchCandidates', () => {
  it('inclui o nome qualificado pela categoria quando há título de seção', () => {
    expect(buildMatchCandidates({ name: 'chocolate', category: 'Bolos no Pote' })).toEqual([
      'chocolate',
      'Bolos no Pote chocolate',
    ]);
  });

  it('não duplica quando o nome já começa com a categoria', () => {
    expect(
      buildMatchCandidates({ name: 'Bolo no Pote Chocolate', category: 'Bolo no Pote' }),
    ).toEqual(['Bolo no Pote Chocolate']);
  });

  it('sem categoria significativa, devolve só o nome cru', () => {
    expect(buildMatchCandidates({ name: 'chocolate' })).toEqual(['chocolate']);
    expect(buildMatchCandidates({ name: 'chocolate', category: 'Geral' })).toEqual(['chocolate']);
  });
});

describe('isCategoryConsistent', () => {
  it('produto coerente com o título da seção', () => {
    expect(
      isCategoryConsistent({ category: 'Bolos no Pote' }, { nome: 'Bolo no Pote Chocolate' }),
    ).toBe(true);
  });

  it('produto incoerente com o título da seção', () => {
    expect(
      isCategoryConsistent({ category: 'Bolos no Pote' }, { nome: 'Mini de Chocolate' }),
    ).toBe(false);
  });

  it('tolera plural no título (Minis → Mini ...)', () => {
    expect(isCategoryConsistent({ category: 'Minis' }, { nome: 'Mini Ferrero Rocher' })).toBe(true);
  });

  it('item sem categoria é sempre coerente', () => {
    expect(isCategoryConsistent({}, { nome: 'Mini de Chocolate' })).toBe(true);
  });
});

describe('bestCatalogMatch — regressão do título de seção', () => {
  it('"chocolate" sob "Bolos no Pote" casa em "Bolo no Pote Chocolate", NÃO em "Mini de Chocolate"', () => {
    const m = bestCatalogMatch({ name: 'chocolate', category: 'Bolos no Pote' }, CATALOG);
    expect(m.product?.nome).toBe('Bolo no Pote Chocolate');
    expect(m.via).toBe('category');
    expect(m.categoryConsistent).toBe(true);
    expect(m.score).toBeGreaterThan(0.9);
    expect(shouldAutoLock(m)).toBe(true);
  });

  it('"banoffe" (typo) sob "Bolos no Pote" casa em "Bolo no Pote Banoffee"', () => {
    const m = bestCatalogMatch({ name: 'banoffe', category: 'Bolos no Pote' }, CATALOG);
    expect(m.product?.nome).toBe('Bolo no Pote Banoffee');
    expect(shouldAutoLock(m)).toBe(true);
  });

  it('nome completo limpo continua casando em si mesmo (sem regressão)', () => {
    const m = bestCatalogMatch(
      { name: 'Bolo no Pote Ninho', category: 'Bolos no Pote' },
      CATALOG,
    );
    expect(m.product?.nome).toBe('Bolo no Pote Ninho');
    expect(m.score).toBeGreaterThan(0.9);
    expect(shouldAutoLock(m)).toBe(true);
  });

  it('Mini correto sob "Minis" trava (plural tolerado)', () => {
    const m = bestCatalogMatch({ name: 'ferrero rocher', category: 'Minis' }, CATALOG);
    expect(m.product?.nome).toBe('Mini Ferrero Rocher');
    expect(shouldAutoLock(m)).toBe(true);
  });
});

describe('shouldAutoLock — "perguntar, não chutar"', () => {
  it('match de score médio incoerente com o título vai pra revisão (não trava)', () => {
    // "ferrero rocher" digitado por engano sob "Bolos no Pote": com a nova preferência
    // por coerência, o produto devolvido passa a ser o melhor coerente da seção (um
    // "Bolo no Pote X") em vez de "Mini Ferrero Rocher". O score é baixo (abaixo do
    // limiar) porque "ferrero rocher" não combina bem com nenhum Bolo no Pote.
    // A asserção essencial — shouldAutoLock === false — é preservada.
    const m = bestCatalogMatch({ name: 'ferrero rocher', category: 'Bolos no Pote' }, CATALOG);
    expect(m.product?.nome).toMatch(/^Bolo no Pote/);
    expect(m.categoryConsistent).toBe(true);
    expect(shouldAutoLock(m)).toBe(false);
  });

  it('abaixo do threshold nunca trava', () => {
    const m = bestCatalogMatch({ name: 'xpto inexistente' }, CATALOG);
    expect(shouldAutoLock(m)).toBe(false);
  });

  it('catálogo vazio não trava nada', () => {
    const m = bestCatalogMatch({ name: 'chocolate', category: 'Bolos no Pote' }, []);
    expect(m.product).toBeNull();
    expect(shouldAutoLock(m)).toBe(false);
  });
});

describe('bestCatalogMatch — regressão A4: milho/Caseirinhos (nunca trava Milho insumo)', () => {
  it('"milho" sob "Caseirinhos" sugere "Mini Caseirinho Milho", NUNCA "Milho" insumo', () => {
    // Caso real: "milho" cru sob seção "Caseirinhos" casava score 1.0 com o insumo
    // "Milho" (id 9) e travava errado. Com a preferência coerente, retorna o produto
    // correto da seção. O score é < 0.72 (string edit), então vai pra revisão (não
    // trava) — mas JÁ com "Mini Caseirinho Milho" pré-selecionado.
    const m = bestCatalogMatch({ name: 'milho', category: 'Caseirinhos' }, CATALOG);
    expect(m.product?.nome).toBe('Mini Caseirinho Milho');
    expect(m.product?.id).toBe(10);
    expect(m.categoryConsistent).toBe(true);
    expect(m.score).toBeLessThan(DEFAULT_MATCH_THRESHOLD);
    expect(shouldAutoLock(m)).toBe(false); // vai pra revisão com sugestão certa
  });

  it('"Mini Caseirinho Milho" sob "Caseirinhos" — exato — trava (A1 parser herdado)', () => {
    // Quando o parser herda corretamente "Mini Caseirinho Milho" (via CATEGORY_PREFIX_MAP
    // + repairItemName da edge function), o score é 1.0 e shouldAutoLock trava.
    const m = bestCatalogMatch(
      { name: 'Mini Caseirinho Milho', category: 'Caseirinhos' },
      CATALOG,
    );
    expect(m.product?.nome).toBe('Mini Caseirinho Milho');
    expect(m.categoryConsistent).toBe(true);
    expect(m.score).toBeGreaterThanOrEqual(DEFAULT_MATCH_THRESHOLD);
    expect(shouldAutoLock(m)).toBe(true);
  });

  it('score 1.0 incoerente via "bare" NÃO trava — bypass removido', () => {
    // Antes: shouldAutoLock tinha "if (score >= 0.92) return true" que travava
    // "milho → Milho" (score 1.0) independente de categoryConsistent.
    // Agora: incoerente + bare nunca trava, independente do score.
    expect(
      shouldAutoLock({
        product: { id: 9, nome: 'Milho' },
        score: 1,
        categoryConsistent: false,
        via: 'bare',
      }),
    ).toBe(false);
  });
});

