/**
 * @module productMatch
 *
 * Match ciente da **categoria/título de seção** entre itens extraídos de uma
 * requisição e o catálogo de produtos (produtos_master).
 *
 * Motivação: mensagens de requisição são hierárquicas — um cabeçalho de seção
 * ("Bolos no Pote") seguido de sub-itens só com o sabor ("chocolate"). Quando o
 * parser de IA dropa o prefixo da categoria, um match só-pelo-nome ancora em
 * qualquer produto com a palavra no nome (ex.: "chocolate" → "Mini de
 * Chocolate"). Estas funções comparam também "categoria + sabor", então
 * "chocolate" sob "Bolos no Pote" casa em "Bolo no Pote Chocolate".
 *
 * Puro: sem React, Supabase ou side-effects — testável isoladamente.
 */

import { normalizeName, similarity } from '@/shared/lib/stringUtils';

/** Item extraído (parcial) que será casado com o catálogo. */
export interface MatchableItem {
  name: string;
  /** Título/cabeçalho da seção a que o item pertence (ex.: "Bolos no Pote"). */
  category?: string;
}

/** Produto de catálogo (forma mínima — qualquer objeto com `id` e `nome`). */
export interface MatchableProduct {
  id: number;
  nome: string;
}

/** Threshold padrão de match fuzzy (alinhado à produção diária). */
export const DEFAULT_MATCH_THRESHOLD = 0.72;

/** Acima disto, um match é forte o bastante pra travar mesmo sem coerência de título. */
export const HIGH_CONFIDENCE = 0.92;

// Palavras de ligação ignoradas ao comparar o título da seção com o nome do produto.
const CATEGORY_STOPWORDS = new Set([
  'de', 'do', 'da', 'no', 'na', 'com', 'e', 'a', 'o', 'os', 'as', 'em', 'sem', 'ao', 'dos', 'das',
]);

/** Reduz plural simples do português ("bolos" → "bolo", "minis" → "mini"). */
const stem = (t: string): string => (t.length > 4 && t.endsWith('s') ? t.slice(0, -1) : t);

/**
 * Constrói os nomes-candidatos para o match fuzzy de um item.
 *
 * Sempre inclui o nome cru. Quando há um título de seção significativo e o nome
 * ainda não começa com ele, inclui também o nome qualificado pela categoria
 * (`"categoria sabor"`), para resgatar o produto completo.
 */
export function buildMatchCandidates(item: MatchableItem): string[] {
  const name = (item.name || '').trim();
  const cat = (item.category || '').trim();
  const candidates = [name];
  const catNorm = normalizeName(cat);
  if (catNorm && catNorm !== 'geral' && !normalizeName(name).startsWith(catNorm)) {
    candidates.push(`${cat} ${name}`.trim());
  }
  return candidates;
}

/**
 * O produto casado é coerente com a categoria/título da seção do item?
 *
 * Verdadeiro quando o nome do produto contém a maioria dos tokens
 * significativos do título (tolerando plural). Itens sem categoria significativa
 * são sempre coerentes (não há título a violar).
 */
export function isCategoryConsistent(
  item: MatchableItem,
  product: Pick<MatchableProduct, 'nome'>,
): boolean {
  const cat = normalizeName((item.category || '').replace(/[/|]+/g, ' '));
  if (!cat || cat === 'geral') return true;

  const prodNorm = normalizeName(product.nome);
  const tokens = cat
    .split(' ')
    .filter((t) => t.length >= 3 && !CATEGORY_STOPWORDS.has(t))
    .map(stem);
  if (tokens.length === 0) return true;

  const hits = tokens.filter((t) => prodNorm.includes(t)).length;
  return hits >= Math.ceil(tokens.length / 2);
}

/** Resultado do match ciente de categoria. Preserva o tipo do produto do catálogo. */
export interface CategoryAwareMatch<T extends MatchableProduct = MatchableProduct> {
  /** Melhor produto encontrado (ou `null` se o catálogo está vazio). */
  product: T | null;
  /** Score de similaridade [0..1] do melhor candidato. */
  score: number;
  /** O produto casado é coerente com o título da seção. */
  categoryConsistent: boolean;
  /** Qual candidato venceu: nome cru (`'bare'`) ou qualificado pela categoria (`'category'`). */
  via: 'bare' | 'category';
}

/**
 * Acha o melhor produto do catálogo para um item, considerando o título da
 * seção. Quando a seção é significativa (categoria não-vazia e ≠ 'geral'),
 * prefere o MELHOR produto **coerente com ela** ao vencedor global de classe
 * errada — mesmo que o coerente tenha score mais baixo. Isso evita que um
 * sabor cru (ex.: "milho") ancore em um produto homônimo de outra classe
 * ("Milho" insumo) quando existe um produto correto na seção ("Mini
 * Caseirinho Milho").
 *
 * Rastreia dois melhores em paralelo:
 *  - `overall` — maior score global (comportamento anterior).
 *  - `consistent` — maior score apenas entre produtos coerentes com a seção.
 *
 * Retorna `consistent` quando a seção é significativa e há ao menos um
 * produto coerente; caso contrário, retorna `overall`.
 */
export function bestCatalogMatch<T extends MatchableProduct>(
  item: MatchableItem,
  catalog: T[],
): CategoryAwareMatch<T> {
  const candidates = buildMatchCandidates(item);
  const catNorm = normalizeName((item.category || '').trim());
  const sectionSignificant = !!catNorm && catNorm !== 'geral';

  let overallBest: T | null = null;
  let overallScore = 0;
  let overallVia: 'bare' | 'category' = 'bare';

  let consistentBest: T | null = null;
  let consistentScore = 0;
  let consistentVia: 'bare' | 'category' = 'bare';

  candidates.forEach((cand, ci) => {
    const v: 'bare' | 'category' = ci === 0 ? 'bare' : 'category';
    for (const p of catalog) {
      const sim = similarity(cand, p.nome);
      if (sim > overallScore) {
        overallScore = sim;
        overallBest = p;
        overallVia = v;
      }
      if (sectionSignificant && isCategoryConsistent(item, p) && sim > consistentScore) {
        consistentScore = sim;
        consistentBest = p;
        consistentVia = v;
      }
    }
  });

  // Quando a seção é significativa e há ao menos um produto coerente, preferir
  // o coerente — mesmo que o score seja menor que o global. O chamador decide
  // se o score é suficiente para travar via shouldAutoLock.
  if (sectionSignificant && consistentBest !== null) {
    return {
      product: consistentBest,
      score: consistentScore,
      categoryConsistent: true,
      via: consistentVia,
    };
  }

  return {
    product: overallBest,
    score: overallScore,
    categoryConsistent: overallBest ? isCategoryConsistent(item, overallBest) : false,
    via: overallVia,
  };
}

/**
 * Decide se um match deve travar automaticamente, ou ir pra revisão manual.
 *
 * Política "perguntar, não chutar":
 *  1. Abaixo do limiar → nunca trava.
 *  2. Coerente com o título da seção + acima do limiar → trava sempre.
 *  3. Incoerente: bypass de alta confiança SÓ via candidato qualificado pela
 *     categoria (`via === 'category'`), nunca via sabor cru (`via === 'bare'`).
 *     Isso impede que "milho" (score 1.0 em "Milho" insumo, via bare) trave
 *     mesmo sendo incoerente com a seção "Caseirinhos".
 */
export function shouldAutoLock(
  match: CategoryAwareMatch,
  threshold: number = DEFAULT_MATCH_THRESHOLD,
  highConfidence: number = HIGH_CONFIDENCE,
): boolean {
  if (!match.product || match.score < threshold) return false;
  if (match.categoryConsistent) return true;
  // Incoerente: bypass de alta confiança APENAS por candidato de categoria
  return match.via === 'category' && match.score >= highConfidence;
}

